cat > "/c/Users/LUCA~1.TAR/AppData/Local/Temp/7/claude/c13e0dd8725d7e31/bba5a6aa-ef31-41c6-938e-c4966a0f023b/scratchpad/tools/check_md.py" <<'EOF'
# Controlla un modulo della dispensa: frontmatter, barra di navigazione, titoli,
# blocchi di codice, callout, wikilink e ancore. Uso: check_md.py <cartella> <file.md> ...
import os
import re
import sys

CONSENTITI = {
    "00 - Indice Generale ITS (MOC)", "00 - Indice AWS (MOC)", "01 - Fondamenti di networking",
    "02 - Reti Wi-Fi e VPN", "03 - Simulazione dei protocolli di rete", "04 - Fondamenti di cloud computing",
    "05 - Classificazione dei servizi cloud", "06 - Immagini, container e registri",
    "07 - Dockerfile, networking e Kubernetes", "99 - Glossario, Comandi e Cheat Sheet AWS",
}
MIEI = {"01 - Fondamenti di networking", "02 - Reti Wi-Fi e VPN", "03 - Simulazione dei protocolli di rete"}
LINGUAGGI = {"powershell", "bash", "dockerfile", "yaml", "python", "json", "http", "text", "mermaid"}
CALLOUT_OK = [
    re.compile(r"^> \[!abstract\] Obiettivi e sintesi$"),
    re.compile(r"^> \[!important\] Concetto chiave — .+"),
    re.compile(r"^> \[!example\] (Laboratorio|Caso pratico) — .+"),
    re.compile(r"^> \[!warning\] Attenzione — .+"),
    re.compile(r"^> \[!success\]- Risposte$"),
]

def titoli(path):
    """Restituisce l'insieme dei titoli (H1-H6) del file, fuori dai blocchi di codice."""
    out, in_code = set(), False
    for riga in open(path, encoding="utf-8"):
        s = riga.rstrip("\n")
        if re.match(r"^(> )?```", s):
            in_code = not in_code
            continue
        if not in_code:
            m = re.match(r"^(#{1,6}) (.+)$", s)
            if m:
                out.add(m.group(2).strip())
    return out

cartella = sys.argv[1]
for nome in sys.argv[2:]:
    path = os.path.join(cartella, nome)
    righe = open(path, encoding="utf-8").read().split("\n")
    print("=" * 70)
    print(nome)
    problemi = []
    # frontmatter
    if righe[0] != "---" or righe[4] != "---" or righe[1] != "tags: [dispensa, its, aws]" or righe[3] != "stato: da-ripassare" or not re.match(r'^modulo: "\d\d"$', righe[2]):
        problemi.append("frontmatter non conforme")
    nav_alto = righe[5]
    ultime = [r for r in righe if r.strip() != ""]
    if ultime[-1] != nav_alto:
        problemi.append("barra di navigazione finale diversa da quella iniziale")
    if not righe[7].startswith("# "):
        problemi.append("H1 non alla riga 8: " + righe[7])
    in_code = False
    lang_stack = None
    for i, s in enumerate(righe, start=1):
        fence = re.match(r"^(> )?```(\S*)", s)
        if fence:
            if not in_code:
                in_code = True
                lang_stack = fence.group(2)
                if lang_stack not in LINGUAGGI:
                    problemi.append(f"riga {i}: blocco di codice senza linguaggio valido ({lang_stack!r})")
            else:
                in_code = False
            continue
        if in_code:
            continue
        m = re.match(r"^(#{2,6}) (.+)$", s)
        if m and re.search(r"[#^\[\]|:]", m.group(2)):
            problemi.append(f"riga {i}: titolo con carattere vietato: {s}")
        if s.startswith("> [!"):
            if not any(p.match(s) for p in CALLOUT_OK):
                problemi.append(f"riga {i}: callout non ammesso: {s}")
        for wl in re.finditer(r"\[\[([^\]]+)\]\]", s):
            dentro = wl.group(1)
            in_tabella = s.lstrip("> ").startswith("|")
            if in_tabella and re.search(r"(?<!\\)\|", dentro):
                problemi.append(f"riga {i}: alias in tabella senza barra protetta: [[{dentro}]]")
            target = re.split(r"\\?\|", dentro)[0]
            file_t, _, ancora = target.partition("#")
            if file_t == "":
                file_t = nome[:-3]
            if file_t not in CONSENTITI:
                problemi.append(f"riga {i}: wikilink verso file non consentito: {file_t}")
                continue
            if ancora:
                if file_t not in MIEI:
                    problemi.append(f"riga {i}: ancora verso modulo di altro autore: {target}")
                else:
                    p2 = os.path.join(cartella, file_t + ".md")
                    if os.path.exists(p2):
                        if ancora not in titoli(p2):
                            problemi.append(f"riga {i}: ancora inesistente: {target}")
                    else:
                        problemi.append(f"riga {i}: (file non ancora scritto) ancora da verificare: {target}")
    testo = "\n".join(righe)
    parole = len(re.findall(r"\w+", testo))
    h2 = [r[3:] for r in righe if r.startswith("## ")]
    print("parole (stima):", parole)
    print("H2:", h2)
    print("problemi:" if problemi else "nessun problema trovato")
    for p in problemi:
        print("  -", p)
EOF
